拿到了参考模式（`uart_recvchars` 在 `serial_io.c:138`，会自动 `while(uart_rxavailable){receive()}` 入环再 post `recvsem`；`up_rxint` 的 critical-section+enable 范式在 nuc1xx/stm32 里都是同一个套路）。下面给你具体怎么搬——直接对着 BK7258 真实寄存器写出来。

## 1. 要搬的范式（CMSDK/stm32 通用）

- **ISR**：清中断标志位 → 调 `uart_recvchars(dev)`（它自己会 `while(rxavailable) receive()` 把 RX FIFO 抽干、推进 recv 环、post `recvsem` 唤醒 `read()`）。**ISR 不直接读 FIFO、不管环**，全交给上 semi。
- **rxint(dev,true)**：进 critical section → 开中断 → race-fix 排空 → 出 critical section。

## 2. ISR 骨架（BK7258，真实寄存器）

```c
/* UART1 MMIO + 系统门（子代理已从 3 源交叉验证的地址/位） */
#define BK7258_UART1_INT_STATUS   (*(volatile uint32_t *)0x45830024u)
#define BK7258_UART1_INT_ENABLE   (*(volatile uint32_t *)0x45830020u)
#define BK7258_SYS_CPU0_INT_EN    (*(volatile uint32_t *)0x44010080u)  /* bit15=UART1 */

#define BK7258_UART_INT_RX_NEED_READ  (1u << 1)   /* rx_fifo_need_read：主 RX 触发 */
#define BK7258_UART_INT_RX_OVERFLOW   (1u << 2)
#define BK7258_UART_INT_RX_PARITY     (1u << 3)
#define BK7258_UART_INT_RX_STOPBIT    (1u << 4)
#define BK7258_UART_INT_RX_FINISH     (1u << 6)   /* rx_finish：空闲/停止结束 */

/* 写 1 清除：只写常量 mask，绝不 read-modify-write 整字（Zephyr §14.5 警告） */
#define BK7258_UART_INT_RX_CLEAR  (BK7258_UART_INT_RX_NEED_READ | \
                                   BK7258_UART_INT_RX_OVERFLOW  | \
                                   BK7258_UART_INT_RX_PARITY    | \
                                   BK7258_UART_INT_RX_STOPBIT   | \
                                   BK7258_UART_INT_RX_FINISH)          /* = 0x76 */

static int bk7258_uart_isr(int irq, FAR void *context, FAR void *arg)
{
  FAR uart_dev_t *dev = (FAR uart_dev_t *)arg;

  BK7258_UART1_INT_STATUS = BK7258_UART_INT_RX_CLEAR;  /* 清 RX 中断 */
  uart_recvchars(dev);                                 /* 抽干 FIFO → post recvsem */
  return OK;
}
```

## 3. rxint + race-fix（你问的重点）

**这个 race 是什么**：上 semi 决定要 `read()` 阻塞等输入时，先调 `rxint(dev,true)` 开 RX 中断。危险窗口在"决定等"和"中断真的开起来"之间——如果恰好这一瞬有一个字节落进 RX FIFO，上 semi 已经在等了但这个字节没触发中断（中断还没开），它就**卡在 FIFO 里**，直到**下一个**字节到来才触发 ISR。在安静的电平上（用户只敲了一个字符就停手），这一个字符就丢了/卡住。

**搬法**：在**同一个 critical section 里**，先开中断，再查 `rxavailable()`，若已有数据就**同步**调一次 `uart_recvchars()` 把遗留字节抽干。critical section 屏蔽了中断，所以不会和真 ISR 抢着抽。

```c
static void bk7258_uart_rxint(FAR uart_dev_t *dev, bool enable)   /* 签名照搬现有 op */
{
  irqstate_t flags = enter_critical_section();

  if (enable)
    {
      /* 三道门，按 外设→片上中断控制器→NVIC 顺序开 */
      BK7258_UART1_INT_ENABLE |= (BK7258_UART_INT_RX_NEED_READ |
                                  BK7258_UART_INT_RX_FINISH);   /* 门① UART 本地 */
      BK7258_SYS_CPU0_INT_EN  |= (1u << 15);                    /* 门② 系统门(最易漏) */
      up_enable_irq(BK7258_IRQ_UART1);                          /* 门③ NVIC slot[31] */

      /* race-fix：开完中断后，若 FIFO 已有遗留字节，立刻同步抽干，
       * 否则该字节要等下一个字节边沿才触发 IRQ（静默线路上永远等不到） */
      if (uart_rxavailable(dev))
        {
          uart_recvchars(dev);
        }
    }
  else
    {
      BK7258_UART1_INT_ENABLE &= ~(BK7258_UART_INT_RX_NEED_READ |
                                   BK7258_UART_INT_RX_FINISH);
      up_disable_irq(BK7258_IRQ_UART1);
    }

  leave_critical_section(flags);
}
```

（注意是**开中断之后再 drain**，不是之前——开之前 drain 仍留窗口：drain 查到空 → 字节落入 → 开中断 → 字节卡住。开之后 drain，被 critical section 保护，无窗口。）

## 4. 另外两个一处一行的小改

```c
/* attach：no-op → 真挂 ISR（NVIC 使能推迟到 rxint） */
static int bk7258_uart_attach(FAR uart_dev_t *dev)
{
  return irq_attach(BK7258_IRQ_UART1, bk7258_uart_isr, dev);
}

/* receive：潜伏 bug——RX 数据在 bit8:15，不是 bit0:7（那是 TX 字段） */
static int bk7258_uart_receive(FAR uart_dev_t *dev, unsigned int *status)
{
  if (status) *status = 0;
  return (int)((BK7258_UART1_FIFO_PORT >> 8) & 0xffu);   /* 原来是 & 0xff */
}
```

加上 `irq.h` 里加 `#define BK7258_IRQ_UART1 (16 + 15) /* = 31 */`。向量 slot[31] 已是 `exception_direct`，NR_IRQS=48 已覆盖，**不动向量表**。

## 5. 实现时要核对的 4 个点（交给子代理动手时盯住）

1. **op 签名**必须逐字匹配 `bk7258_serial.c` 现有 ops 表（`uart_dev_t *` vs `struct uart_dev_s *`、`receive` 的第二参）——我上面用的是占位写法。
2. **三道门顺序**不能漏门② `0x44010080 bit15`——纯 NuttX 视角看 IRQ 号/向量/NVIC 都对，但 BK7258 多一层片上中断控制器，这道门不开 ISR 永远不进。
3. **写 1 清除用常量 mask**，不要 RMW 整字。
4. `receive` 的 bit8:15 是和 TX 共享同一个 32 位 `fifo_port` 字的高字节（SDK `uart_ll_read_byte` 取 `rx_fifo_data_out` 即 bit8:15 双向印证）。

---

方案就是这样。要我让子代理按这个动手改 `bk7258_serial.c` + `irq.h`，然后 rebuild 吗？改完你重新烧 all-app.bin，460800 终端敲键盘应该就能回显/执行命令了。

