/* Diagnostic 32-bit hex dumper.  Steps the shift from 28 down to 0 in
 * fours so we never evaluate v >> 32 (ARM undefined behaviour).  Used to
 * dump the four RX-interrupt gate registers once, right after rxint(true)
 * opens them, so board-side observation can confirm each write landed.
 */

static void bk7258_serial_diag_puthex32(uint32_t v)
{
  static const char hexdigits[] = "0123456789abcdef";
  int s;

  for (s = 28; s >= 0; s -= 4)
    {
      bk7258_serial_diag_putc(hexdigits[(v >> s) & 0xf]);
    }
}

